import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span

class RoundSpansTests(unittest.TestCase):
    def test_label_format(self):
        self.assertEqual(
            round_spans([Span(540, 1035)], 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_rounds_to_nearest(self):
        # 09:07 -> 09:00, 17:06 -> 17:00
        self.assertEqual(
            round_spans([Span(547, 1026)], 15),
            ["09:00-17:00 (8h 0m)"],
        )
        # 09:08 -> 09:15, 17:08 -> 17:15
        self.assertEqual(
            round_spans([Span(548, 1028)], 15),
            ["09:15-17:15 (8h 0m)"],
        )

    def test_halfway_goes_up(self):
        self.assertEqual(
            round_spans([Span(60, 128)], 15),
            ["01:00-02:15 (1h 15m)"],
        )
        self.assertEqual(
            round_spans([Span(67, 120)], 15),
            ["01:00-02:00 (1h 0m)"],
        )
        self.assertEqual(
            round_spans([Span(68, 120)], 15),
            ["01:15-02:00 (0h 45m)"],
        )

    def test_end_of_day(self):
        self.assertEqual(
            round_spans([Span(1400, 1439)], 30),
            ["23:30-24:00 (0h 30m)"],
        )

    def test_many_spans_keep_order(self):
        spans = [Span(60, 120), Span(0, 30)]
        labels = round_spans(spans, 10)
        self.assertEqual(
            labels,
            ["01:00-02:00 (1h 0m)", "00:00-00:30 (0h 30m)"],
        )

    def test_empty(self):
        self.assertEqual(round_spans([], 15), [])

    def test_collapsed_span(self):
        self.assertEqual(
            round_spans([Span(61, 64)], 15),
            ["01:00-01:00 (0h 0m)"],
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120, 2.5):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(60, 120)], step)

    def test_bad_step_raises_for_empty_input(self):
        with self.assertRaises(ValueError):
            round_spans([], 0)

    def test_good_steps_accepted(self):
        for step in (1, 5, 6, 10, 15, 30, 60):
            with self.subTest(step=step):
                labels = round_spans([Span(60, 600)], step)
                self.assertEqual(len(labels), 1)

if __name__ == "__main__":
    unittest.main()
